// src/ai/errors/error-center.ts
// Error Detection Center logic. Every item comes from the engine's decision log, its fault states,
// or the deterministic analysis. Nothing here is generated by a language model.
// NO React, Zustand, or Phaser imports.

import type { DecisionLogEntry, FaultState, PlayerAction } from '@simulation/types'
import { analyzeMission } from '../analysis/mission-analysis'
import type { SimulationContext } from '../simulation-context'

export type ErrorSeverity = 'critical' | 'warning' | 'optimization'
export type ErrorResource = 'oxygen' | 'water' | 'food' | 'energy' | 'radiation' | 'decision'

export interface ErrorItem {
  readonly id: string
  readonly severity: ErrorSeverity
  readonly resource: ErrorResource
  readonly title: string
  readonly day: number | null
  readonly decision: string
  /** What the engine recorded happened. */
  readonly happened: string
  /** The rule the engine applied, in its own words. Only shown when the engine recorded one. */
  readonly ruleNote: string
  readonly impact: string
  readonly avoid: string
  readonly betterChoice: string
  readonly lesson: string
}

export interface ErrorSummary {
  readonly total: number
  readonly critical: number
  readonly warnings: number
  readonly optimizations: number
}

export interface ErrorFilter {
  readonly severity?: ErrorSeverity
  readonly resource?: ErrorResource
}

const RESOURCE_OF_FAULT: Readonly<Record<FaultState, ErrorResource>> = {
  OXYGEN_DEPLETED: 'oxygen',
  WATER_DEPLETED: 'water',
  FOOD_DEPLETED: 'food',
  POWER_CRITICAL: 'energy',
  RADIATION_HIGH: 'radiation',
  RADIATION_CRITICAL: 'radiation',
}

const FAULT_IMPACT: Readonly<Record<FaultState, string>> = {
  OXYGEN_DEPLETED: 'Air supply is gone; the crew cannot survive for long without it.',
  WATER_DEPLETED: 'Drinking water is gone; dehydration sets in quickly.',
  FOOD_DEPLETED: 'Food is gone; the crew weakens over the following days.',
  POWER_CRITICAL: 'Life support and equipment depend on power, so every system is at risk.',
  RADIATION_HIGH: 'Dose is above the high threshold; further exposure should be limited.',
  RADIATION_CRITICAL: 'Dose is above the critical threshold; surface operations must stop.',
}

function betterFor(action: PlayerAction): string {
  switch (action.type) {
    case 'EMERGENCY_RATION': return 'Plan food earlier so that emergency rations are a last resort.'
    case 'RESOLVE_EVENT': return 'Choose the option that protects life support first, then compare the costs.'
    case 'ADVANCE_DAY': return 'Check critical resources and faults before advancing the day.'
  }
}

function actionText(action: PlayerAction): string {
  switch (action.type) {
    case 'ADVANCE_DAY': return 'Advanced the day'
    case 'RESOLVE_EVENT': return `Resolved event ${action.eventId} with choice ${action.choiceId}`
    case 'EMERGENCY_RATION': return 'Used emergency rations'
  }
}

function resourceOf(action: PlayerAction): ErrorResource {
  if (action.type === 'EMERGENCY_RATION') return 'food'
  return 'decision'
}

export function buildErrorItems(decisionLog: readonly DecisionLogEntry[], context: SimulationContext): ErrorItem[] {
  const items: ErrorItem[] = []

  // 1. Decisions the engine recorded as not optimal.
  decisionLog.forEach((entry, index) => {
    if (entry.wasOptimal) return
    items.push({
      id: `decision:${index}`,
      severity: entry.action.type === 'EMERGENCY_RATION' ? 'warning' : 'optimization',
      resource: resourceOf(entry.action),
      title: `${actionText(entry.action)} was not the best choice`,
      day: entry.missionDay,
      decision: actionText(entry.action),
      happened: entry.resultSummary.trim() || 'The engine did not record what happened.',
      ruleNote: 'The engine marked this decision as not optimal.',
      impact: entry.resultSummary.trim() || 'The engine did not record a detailed impact.',
      avoid: betterFor(entry.action),
      betterChoice: betterFor(entry.action),
      lesson: 'Review this decision type before the next mission.',
    })
  })

  // 2. Engine faults are critical errors that happened to the base.
  for (const fault of context.faultStates) {
    items.push({
      id: `fault:${fault}`,
      severity: 'critical',
      resource: RESOURCE_OF_FAULT[fault],
      title: `${fault.replace(/_/g, ' ').toLowerCase()} reported by the simulation`,
      day: context.missionDay,
      decision: 'Current state of the base',
      happened: `The simulation set ${fault}.`,
      ruleNote: 'The engine sets this fault when the resource or dose crosses its threshold.',
      impact: FAULT_IMPACT[fault],
      avoid: 'Watch the matching resource each day and act before it reaches its threshold.',
      betterChoice: 'Restore the resource or protect the crew before advancing the day.',
      lesson: 'Faults are the engine\'s own record of failure; read them before every decision.',
    })
  }

  // 3. Resources that are low but not yet failed (analysis threshold).
  const analysis = analyzeMission(context)
  for (const r of analysis.resources) {
    if (r.status === 'low') {
      items.push({
        id: `low:${r.resource}`,
        severity: 'warning',
        resource: r.resource,
        title: `${r.resource[0]?.toUpperCase()}${r.resource.slice(1)} is running low`,
        day: context.missionDay,
        decision: 'Current resource level',
        happened: `${r.percent}% of the starting level remains.`,
        ruleNote: 'Analysis threshold, not an engine rule.',
        impact: 'If use continues at this pace the reserve will reach zero.',
        avoid: 'Reduce use or increase supply before the reserve drops further.',
        betterChoice: 'Plan the next supply action now.',
        lesson: 'Low reserves leave little room for surprises such as storms or events.',
      })
    }
  }

  return items
}

export function summarizeErrors(items: readonly ErrorItem[]): ErrorSummary {
  return {
    total: items.length,
    critical: items.filter((i) => i.severity === 'critical').length,
    warnings: items.filter((i) => i.severity === 'warning').length,
    optimizations: items.filter((i) => i.severity === 'optimization').length,
  }
}

export function filterErrors(items: readonly ErrorItem[], filter: ErrorFilter): ErrorItem[] {
  return items.filter((i) =>
    (filter.severity === undefined || i.severity === filter.severity) &&
    (filter.resource === undefined || i.resource === filter.resource),
  )
}
